namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class ProcessingJobFactory(string resourceName = null, Action<Humidifier.SageMaker.ProcessingJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.ProcessingJob>(resourceName)
{

    internal List<InnerProcessingJobProcessingInputsObjectFactory> ProcessingInputsFactories { get; set; } = [];

    internal InnerProcessingJobProcessingResourcesFactory ProcessingResourcesFactory { get; set; }

    internal InnerProcessingJobStoppingConditionFactory StoppingConditionFactory { get; set; }

    internal InnerProcessingJobExperimentConfigFactory ExperimentConfigFactory { get; set; }

    internal InnerProcessingJobNetworkConfigFactory NetworkConfigFactory { get; set; }

    internal InnerProcessingJobProcessingOutputConfigFactory ProcessingOutputConfigFactory { get; set; }

    internal InnerProcessingJobAppSpecificationFactory AppSpecificationFactory { get; set; }

    protected override Humidifier.SageMaker.ProcessingJob Create()
    {
        var processingJobResult = CreateProcessingJob();
        factoryAction?.Invoke(processingJobResult);

        return processingJobResult;
    }

    private Humidifier.SageMaker.ProcessingJob CreateProcessingJob()
    {
        var processingJobResult = new Humidifier.SageMaker.ProcessingJob
        {
            GivenName = InputResourceName,
        };

        return processingJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.ProcessingJob result)
    {
        base.CreateChildren(result);

        result.ProcessingInputs = ProcessingInputsFactories.Any() ? ProcessingInputsFactories.Select(x => x.Build()).ToList() : null;
        result.ProcessingResources ??= ProcessingResourcesFactory?.Build();
        result.StoppingCondition ??= StoppingConditionFactory?.Build();
        result.ExperimentConfig ??= ExperimentConfigFactory?.Build();
        result.NetworkConfig ??= NetworkConfigFactory?.Build();
        result.ProcessingOutputConfig ??= ProcessingOutputConfigFactory?.Build();
        result.AppSpecification ??= AppSpecificationFactory?.Build();
    }

} // End Of Class

